def run(out:Path, tracked:Path):
 d=pd.read_pickle(out/'prepared-development.pkl'); rows=table(); coverage=pd.read_csv(out/f'{PREFIX}-champion-archetype-coverage.csv'); audit=pd.read_csv(out/f'{PREFIX}-cutoff-audit.csv'); th=thresholds(rows)
 output=rows.copy(); output['P1_prediction']=output.S30_prediction; output.loc[d.index,'P1_prediction']=d.P1_prediction
