 output['S30_team_total']=output.groupby(['prediction_period_id','team_id']).S30_prediction.transform('sum');output['structural_support']=rows.structural_support;output['fold_or_year_authority']=np.where(output.index.isin(d.index),'DEVELOPMENT_OOF','NOT_RUN');output.to_csv(tracked,index=False,float_format='%.17g')
