 metrics={'P0_S30':calibration(d,'S30_prediction'),'P1_DYNAMIC_PLAYSTYLE':calibration(d,'P1_prediction')};ranking={'P0_S30':rank(d,'S30_prediction',th),'P1_DYNAMIC_PLAYSTYLE':rank(d,'P1_prediction',th)};allocation={'P0_S30':shares(d,'S30_prediction'),'P1_DYNAMIC_PLAYSTYLE':shares(d,'P1_prediction')};rm=role_metrics(d); role_delta={r:float(g[g.arm.eq('P1_DYNAMIC_PLAYSTYLE')].MAE.iloc[0]/g[g.arm.eq('P0_S30')].MAE.iloc[0]-1) for r,g in rm.groupby('role')};deltas={k:ranking['P1_DYNAMIC_PLAYSTYLE'][k]-ranking['P0_S30'][k] for k in ('NDCG',*RECALLS)};positive={k:int(sum(rank(g,'P1_prediction',th)[k]-rank(g,'S30_prediction',th)[k]>0 for _,g in d.groupby('fold_id'))) for k in deltas};qual=[k for k,v in deltas.items() if v>=(.01 if k=='NDCG' else .02) and positive[k]>=2];ad={k:allocation['P1_DYNAMIC_PLAYSTYLE'][k]-allocation['P0_S30'][k] for k in allocation['P0_S30']};improved=[k for k,v in ad.items() if (v<0 if k=='player_share_MAE' else (abs(allocation['P1_DYNAMIC_PLAYSTYLE'][k]-1)<abs(allocation['P0_S30'][k]-1) if k=='share_SD_ratio' else v>0))]
